Translate("ptBR", "tanaris", {
	title = "Tanaris",
	aliases = { "o deserto de Tanaris", "Deserto de Tanaris" },
	sections = {
		{
			title = "Resumo",
			text = [=[Tanaris é o grande deserto do sul de {link:kalimdor}Kalimdor{/link}. Suas dunas vão dos penhascos de {link:thousand-needles}Mil Agulhas{/link} ao mar do sul, e da borda verde da {link:un-goro-crater}Cratera Un'Goro{/link} a uma costa de praias quentes e enseadas escondidas. A chuva quase nunca cai. Todo poço vale uma morte, e toda poça d'água atrai algo sedento. No norte ergue-se {link:gadgetzan}Geringontzan{/link}, uma cidade goblin murada que fez da água um negócio. À sua volta, as areias guardam coisas mais antigas: os templos partidos dos trolls, os portões de pedra selados de um lugar chamado {link:valley-of-the-watchers}Uldum{/link} e uma grande caverna nos penhascos do leste onde, dizem, habitam os dragões do tempo.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica diz quando a terra se tornou deserto, ou o que era antes. Os trolls são seus mais antigos senhores lembrados. Nos dias de seu império, uma tribo de trolls do deserto ergueu a cidade de {red:zul-farrak}Zul'Farrak{/red} entre as dunas do norte, e espalhou santuários e povoados pelas areias ao sul e a leste. A maioria deles hoje está em ruínas. Mais antigas ainda são as obras dos titãs. No sudoeste, no {link:valley-of-the-watchers}Vale dos Vigilantes{/link}, estátuas gigantes erguem-se diante de portões selados que nenhuma mão viva abriu, e os estudiosos dos discos de {link:uldaman}Uldaman{/link} acreditam que esses portões e os registros dos titãs estão ligados.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Tanaris pertence a quem consegue guardar água. Os goblins do {link:steamwheedle-cartel}Cartel Bondebico{/link} governam {link:gadgetzan}Geringontzan{/link}, e sua companhia de águas bombeia os poços da cidade. Fora das muralhas, {link:wastewander-nomads}os nômades{/link} Wastewander tomaram quase todos os outros poços do deserto. Agora chegou algo pior. Enxames de insetos surgiram da areia no oeste e no sul, e estão secando as poças. Os estudiosos de Geringontzan os chamam de {link:qiraji}silitídeos{/link}, e temem que haja uma mente por trás deles. {link:ogres}Ogros{/link} Dunamalho construíram um acampamento no ermo do sul. Os {link:sandfury-trolls}trolls Sandfury{/link} vigiam de Zul'Farrak. Na costa, {link:southsea-pirates}piratas dos Mares do Sul{/link} dominam uma enseada murada a uma curta caminhada ao sul do porto do Cartel.

O Cartel não está parado. Seus navios ainda partem do {link:steamwheedle-port}Porto de Bondebico{/link} para a {link:booty-bay}Angra do Butim{/link}, e uma rota mais nova os leva a {link:powderfuse-port}Powderfuse Port{/link}, em {link:riverglades}Riverglades{/link}, do outro lado do mar.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os goblins de {link:gadgetzan}Geringontzan{/link}.{/b} Engenheiros, alquimistas, ferreiros e mercadores que vendem a qualquer um, e cujos brutamontes garantem que ninguém lute dentro das muralhas.
• {b}Os {link:wastewander-nomads}nômades Wastewander{/link}.{/b} Bandidos e ladrões das areias do leste, que dominam os poços e revendem a água aos sedentos.
• {b}Os {link:sandfury-trolls}trolls Sandfury{/link}.{/b} A tribo do deserto de Zul'Farrak e das ruínas ao redor, conhecida pela crueldade e pela magia sombria.
• {b}Os silitídeos.{/b} Insetos das colmeias Centipaar, que cavaram seus covis no {link:the-noxious-lair}Covil Nóxio{/link} e na {link:the-gaping-chasm}Fenda Hazzali{/link}.
• {b}Os ogros Dunamalho.{/b} Um bando de nômades recém-chegados ao deserto do sul.
• {b}Os {link:southsea-pirates}piratas dos Mares do Sul{/link}.{/b} Flibusteiros que atacam os navios do Cartel a partir da {link:lost-rigger-cove}Enseada do Armador Perdido{/link}.
• {b}Feras da areia.{/b} Basiliscos de couro como vidro, escorpídeos, hienas, grandes aves de fogo e os moitagulhas ambulantes do sudoeste.]=],
		},
		{
			title = "História",
			text = [=[• {b}O Império Troll.{/b} Os trolls do deserto construíram Zul'Farrak e adoravam uma grande hidra que chamavam de Gahz'rilla. Ornamentos entalhados desse deus ainda jazem enterrados nas areias de seus antigos povoados.
• {b}A Chegada do Cartel.{/b} Em eras posteriores, os goblins do {link:steamwheedle-cartel}Cartel Bondebico{/link} vieram ao deserto e construíram {link:gadgetzan}Geringontzan{/link} e o {link:steamwheedle-port}Porto de Bondebico{/link}. Nenhuma crônica registra o ano.
• {b}Os Dias de Hoje.{/b} Os poços estão perdidos, os insetos estão se erguendo, e a cidade que vende água começou a contratar toda espada que consegue encontrar.]=],
		},
		{
			title = "Saber das Areias",
			text = [=[• Os viajantes que morrem no deserto perto de {link:gadgetzan}Geringontzan{/link} são enterrados num pequeno cemitério fora das muralhas. Dizem que um espírito chamado Gaeriyan espera nas colinas ao norte, e que só fala com os que atravessaram para o outro lado.
• Uma tartaruga perdida chamada Tooga vagueia pelo deserto em busca de sua esposa Torta, que o espera ao sul do {link:steamwheedle-port}Porto de Bondebico{/link}.
• Os goblins de Geringontzan dizem que o rum do Porto de Bondebico é grosso como cascalho e queima como lava. Dizem isso como elogio.]=],
		},
	},
})

Translate("ptBR", "gadgetzan", {
	title = "Geringontzan",
	sections = {
		{
			title = "Resumo",
			text = [=[Geringontzan é a capital goblin do deserto, uma cidade murada no norte de {link:tanaris}Tanaris{/link}. O {link:steamwheedle-cartel}Cartel Bondebico{/link} a construiu, e como seus portos irmãos ela está aberta à {link:alliance}Aliança{/link} e à {link:horde}Horda{/link} igualmente. Os brutamontes de Geringontzan andam por suas ruas e tratam com dureza qualquer um que saque uma arma. A cidade vive de sua torre d'água e de seus poços, mantidos pela {link:gadgetzan-water-company}Companhia de Águas de Geringontzan{/link}. À volta deles amontoam-se o Gizmorium, forjas, uma estalagem, um banco e as oficinas de mestres engenheiros goblins. Grifos e mantícoras pousam aqui lado a lado.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[A conversa da estalagem é sobre poços perdidos, recompensas pelos nômades e insetos estranhos no oeste. Estudiosos vêm comprar o que os goblins sabem. Ferreiros vêm pelos moldes de {link:krinkle-goodsteel}Krinkle Goodsteel{/link}, e o mercador de tecidos {link:vizzklick}Vizzklick{/link} ainda se alegra com a morte do {link:trade-master-kovic}Mestre de Comércio Kovic{/link}.]=],
		},
	},
})

Translate("ptBR", "steamwheedle-port", {
	title = "Porto de Bondebico",
	sections = {
		{
			title = "Resumo",
			text = [=[O Porto de Bondebico é o porto do Cartel na costa leste de {link:tanaris}Tanaris{/link}. Seus navios levam carga para a {link:booty-bay}Angra do Butim{/link}, e os piratas da costa mantêm listas de quais valem a pena tomar. O {link:security-chief-bilgewhizzle}Chefe de Segurança Bilgewhizzle{/link} tem a tarefa de manter a paz. {link:stoley}Stoley{/link} serve o famoso rum de porão do porto, e um estudioso troll chamado {link:yeh-kinya}Yeh'kinya{/link} estuda antigas profecias entre os caixotes. Nestes dias, um mestre do cais também envia navios através do mar para {link:powderfuse-port}Powderfuse Port{/link}. Ao sul do porto, à vista das docas, fica a {link:lost-rigger-cove}Enseada do Armador Perdido{/link}.]=],
		},
	},
})

Translate("ptBR", "lost-rigger-cove", {
	title = "Enseada do Armador Perdido",
	sections = {
		{
			title = "Resumo",
			text = [=[A Enseada do Armador Perdido é uma cidade pirata na costa leste de {link:tanaris}Tanaris{/link}, murada com madeira e assentada numa praia estreita abaixo dos penhascos. Os {link:southsea-pirates}piratas dos Mares do Sul{/link} guardam aqui seus navios e seu saque. Da enseada, atacam os navios do Cartel. Aqui o Capitão Cuergo escondeu o rum que roubou do {link:steamwheedle-port}Porto de Bondebico{/link}, e aqui vive {link:andre-firebeard}Andre Firebeard{/link}, o pirata por cuja cabeça o Cartel pôs um preço.]=],
		},
	},
})

Translate("ptBR", "caverns-of-time", {
	title = "Cavernas do Tempo",
	sections = {
		{
			title = "Resumo",
			text = [=[Nas montanhas do leste de {link:tanaris}Tanaris{/link}, uma vasta caverna se abre na rocha. Chama-se Cavernas do Tempo. Contos antigos dizem que é o covil dos {red:bronze-dragonflight}dragões bronze{/red} e de seu senhor {red:nozdormu}Nozdormu{/red}, o Atemporal, a quem os titãs encarregaram de vigiar os caminhos do tempo. Nenhum viajante destes dias contou o que há lá dentro.]=],
		},
	},
})

Translate("ptBR", "valley-of-the-watchers", {
	title = "Vale dos Vigilantes",
	aliases = { "Uldum", "os portões selados de Uldum" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale dos Vigilantes fica no sudoeste de {link:tanaris}Tanaris{/link}. Figuras gigantes de pedra dos titãs erguem-se ali na areia, e entre elas elevam-se grandes portões selados. Os estudiosos do {link:thunder-bluff}Penhasco do Trovão{/link} acreditam que os portões levam a Uldum, um lugar que a maioria considera um mito. Diante dos portões há um pedestal. Quando os discos de platina de {link:uldaman}Uldaman{/link} são trazidos a ele, surge um vigia de pedra de Norgannon, que recusa a entrada a todos que não têm as Placas de Uldum. Ali perto, no Posto de Gunstan, um garimpeiro da {link:explorers-league}Liga dos Exploradores{/link} mantém seu acampamento.]=],
		},
	},
})

Translate("ptBR", "thistleshrub-valley", {
	title = "Vale Moitagulhas",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale Moitagulhas é um jardim de cactos no oeste de {link:tanaris}Tanaris{/link}, onde as dunas encontram os penhascos abaixo da {link:un-goro-crater}Cratera Un'Goro{/link}. Suas plantas andam. Moitagulhas retorcidos e seus moldadores de raízes guardam o vale, e coletores de orvalho armazenam água em suas glândulas. Foi de uma dessas glândulas que {link:marin-noggenfogger}Marin Noggenfogger{/link} preparou seu elixir. O troll {link:tran-rek}Tran'rek{/link} há muito deseja entrar no vale, mas não o bastante para ir até lá pessoalmente.]=],
		},
	},
})

Translate("ptBR", "eastmoon-ruins", {
	title = "Ruínas de Lunaleste",
	aliases = { "Ruínas de Lunassul" },
	sections = {
		{
			title = "Resumo",
			text = [=[As Ruínas de Lunaleste e de Lunassul são os restos de povoados trolls no meio do deserto, bem ao sul de Zul'Farrak. Nada de seu povo resta além de pedra quebrada. Caçadores de tesouros cavam aqui atrás de pequenos entalhes da hidra Gahz'rilla, feitos de uma pedra estranha que o goblin {link:marvon-rivetseeker}Marvon Rivetseeker{/link} chama de Gahz'ridian. Nestes dias, bandos errantes de ogros Dunamalho se instalaram nas ruínas.]=],
		},
	},
})

Translate("ptBR", "broken-pillar", {
	title = "Pilar Partido",
	sections = {
		{
			title = "Resumo",
			text = [=[O Pilar Partido é uma ruína solitária no coração de {link:tanaris}Tanaris{/link}, uma coluna despedaçada deixada pelos antigos construtores trolls. Aqui o estudioso goblin {link:marvon-rivetseeker}Marvon Rivetseeker{/link} armou seu acampamento. Ele viajou de {link:ratchet}Vila Catraca{/link} ao deserto para aprender o que suas cidades trolls caídas podem ensinar, e o viajante que quiser ouvir sobre o {link:temple-of-atal-hakkar}Templo Submerso{/link} precisa vir encontrá-lo aqui.]=],
		},
	},
})

Translate("ptBR", "sandsorrow-watch", {
	title = "Posto Silitriste",
	sections = {
		{
			title = "Resumo",
			text = [=[O Posto Silitriste é um posto avançado troll no noroeste de {link:tanaris}Tanaris{/link}, entre {link:gadgetzan}Geringontzan{/link} e Zul'Farrak. Os {link:sandfury-trolls}trolls Sandfury{/link} o mantêm como posto de guarda de sua cidade. Ao lado dele fica uma das raras poças de água doce do deserto. Quando um agrimensor da {link:gadgetzan-water-company}Companhia de Águas de Geringontzan{/link} veio testar essa poça, algo surgiu da areia e atacou. Foi o primeiro sinal de que os insetos do oeste haviam chegado tão ao norte.]=],
		},
	},
})

Translate("ptBR", "dunemaul-compound", {
	title = "Complexo Dunamalho",
	sections = {
		{
			title = "Resumo",
			text = [=[O Complexo Dunamalho é um acampamento {link:ogres}ogro{/link} no deserto do sul de {link:tanaris}Tanaris{/link}. Um grande bando de ogros nômades chegou aqui não faz muito tempo e cercou com muros uma larga faixa de areia. Seu líder é {link:gor-marok-the-ravager}Gor'marok, o Devastador{/link}. Bandos menores saem do complexo e se espalham pelo deserto. {link:gadgetzan}Geringontzan{/link} teme que os ogros estejam reunindo forças, e pagaria bem para vê-los derrotados antes disso.]=],
		},
	},
})

Translate("ptBR", "the-noxious-lair", {
	title = "Covil Nóxio",
	aliases = { "o Covil Nóxio" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Covil Nóxio é uma colmeia dos insetos Centipaar no oeste de {link:tanaris}Tanaris{/link}. Antes de eles chegarem, havia poças de água aqui. Os insetos as secaram. Seus túneis fervilham de operários, vespas e ferroadores, e os goblins que primeiro estudaram seus corpos descobriram que essas criaturas não se pareciam com nada que já tinham visto, como se alguma vontade de fora as movesse. Foi aqui que os estudiosos de {link:gadgetzan}Geringontzan{/link} aprenderam pela primeira vez o nome dos {link:qiraji}silitídeos{/link}.]=],
		},
	},
})

Translate("ptBR", "the-gaping-chasm", {
	title = "Fenda Hazzali",
	aliases = { "a Fenda Hazzali" },
	sections = {
		{
			title = "Resumo",
			text = [=[{link:the-cleft}A Fenda{/link} Hazzali é uma fenda profunda nas areias a sudeste de {link:gadgetzan}Geringontzan{/link}. Os Centipaar fizeram nela uma segunda colmeia, o que mostrou aos goblins que os insetos dominavam não uma região do deserto, mas duas. O Agrimensor Júnior Scrimshank saiu para mapear a fenda e nunca voltou. Só seu equipamento de agrimensura foi encontrado. Um robô gnômico de retorno também caiu perto de sua borda, longe de seu criador na {link:booty-bay}Angra do Butim{/link}.]=],
		},
	},
})

Translate("ptBR", "waterspring-field", {
	title = "Campo das Minas d'Água",
	sections = {
		{
			title = "Resumo",
			text = [=[O Campo das Minas d'Água é um trecho do deserto do leste onde antes ficavam os poços da {link:gadgetzan-water-company}Companhia de Águas de Geringontzan{/link}. Os {link:wastewander-nomads}nômades Wastewander{/link} os tomaram, e ainda os dominam. Seus bandidos e ladrões acampam ao lado das bombas roubadas, e seus magos das sombras e assassinos vigiam mais a leste e ao sul. A Companhia de Águas conta cada um desses poços como sua propriedade, e pôs um preço na cabeça do líder dos nômades.]=],
		},
	},
})

Translate("ptBR", "gadgetzan-water-company", {
	title = "Companhia de Águas de Geringontzan",
	aliases = { "Cia. de Águas de Geringontzan", "Companhia de Águas", "a Companhia de Águas" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Companhia de Águas de Geringontzan mantém os poços e as bombas de {link:gadgetzan}Geringontzan{/link}, e num deserto isso a torna o negócio mais importante de {link:tanaris}Tanaris{/link}. Seus engenheiros cavam os poços, seus operadores de torneira cuidam da torre, e seus agrimensores vasculham as areias em busca de novas fontes. Ela vende água, como vende tudo, por um preço.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[A companhia está em guerra. Os {link:wastewander-nomads}nômades Wastewander{/link} tomaram quase todos os seus poços além das muralhas, assassinaram seus trabalhadores e roubaram seus estoques. O {link:chief-engineer-bilgewhizzle}Engenheiro-chefe Bilgewhizzle{/link} pôs recompensas pelos nômades e por seu líder, o {link:caliph-scorpidsting}Califa Scorpidsting{/link}, e o Operador de Torneira Luglunket paga por cada odre de água tomado de volta deles. Enquanto isso, o {link:senior-surveyor-fizzledowser}Agrimensor Sênior Fizzledowser{/link} envia agrimensores juniores para encontrar água nova, e eles encontraram coisa pior que nômades. Insetos estão secando as poças livres do oeste, e um dos agrimensores da companhia já morreu na {link:the-gaping-chasm}Fenda Hazzali{/link}. A companhia, que costuma vender o que descobre, decidiu dar de graça seu relatório sobre os insetos a qualquer um que o queira ler.]=],
		},
		{
			title = "Estrutura",
			text = [=[• {b}O {link:chief-engineer-bilgewhizzle}Engenheiro-chefe Bilgewhizzle{/link}{/b} lidera a luta da companhia por seus poços.
• {b}O {link:senior-surveyor-fizzledowser}Agrimensor Sênior Fizzledowser{/link}{/b} lidera a busca por água nova.
• {b}O Operador de Torneira Luglunket{/b} cuida da torre d'água e de suas recompensas.
• {b}O {link:security-chief-bilgewhizzle}Chefe de Segurança Bilgewhizzle{/link}{/b}, do {link:steamwheedle-port}Porto de Bondebico{/link}, tem o título de Segurança da Cia. de Águas.]=],
		},
	},
})

Translate("ptBR", "wastewander-nomads", {
	title = "Nômades Wastewander",
	aliases = { "Wastewander", "nômades Wastewander", "os nômades" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os nômades Wastewander são os fora da lei do deserto do leste de {link:tanaris}Tanaris{/link}. São bandidos, ladrões e assassinos, e fizeram o que nenhum exército conseguiu: tomaram dos goblins a água de Tanaris. Quase todo poço fora das muralhas de {link:gadgetzan}Geringontzan{/link} é deles. Levam a água em odres e vivem dela, enquanto a cidade que construiu os poços precisa comprar fontes de energia e pagar recompensas para reconquistá-los.]=],
		},
		{
			title = "Hierarquia",
			text = [=[• {b}Bandidos e ladrões{/b} dominam os poços mais próximos, a leste de {link:gadgetzan}Geringontzan{/link}.
• {b}Ladinos, assassinos e magos das sombras{/b} são as fileiras mais fortes, e ficam mais a leste e a sudeste.
• {b}O {link:caliph-scorpidsting}Califa Scorpidsting{/link}{/b} lidera a todos.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[A {link:gadgetzan-water-company}Companhia de Águas{/link} os chama de invasores e assassinos. Contratou forasteiros para reduzir seus números, e espera que a morte de seu líder finalmente os expulse dos poços.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica conta de onde vieram os Wastewander, ou quando chegaram pela primeira vez ao deserto.]=],
		},
	},
})

Translate("ptBR", "southsea-pirates", {
	title = "Piratas dos Mares do Sul",
	aliases = { "Southsea", "piratas dos Mares do Sul", "Os Flibusteiros dos Mares do Sul", "os piratas dos Mares do Sul" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os piratas dos Mares do Sul são flibusteiros dos mares do sul. Atacam as costas mercantes de {link:kalimdor}Kalimdor{/link} a partir de portos escondidos, e sua presa favorita são os navios do {link:steamwheedle-cartel}Cartel Bondebico{/link}. Em {link:tanaris}Tanaris{/link}, dominam a {link:lost-rigger-cove}Enseada do Armador Perdido{/link}, uma cidade murada na praia ao sul do {link:steamwheedle-port}Porto de Bondebico{/link}. Outro bando deles perturba a costa ao sul de {link:ratchet}Vila Catraca{/link}, nos {link:the-barrens}Sertões{/link}.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[Os piratas da {link:lost-rigger-cove}Enseada do Armador Perdido{/link} roubaram o rum do {link:steamwheedle-port}Porto de Bondebico{/link} e carregam os próprios horários de navegação do porto, marcados com anotações sobre quais navios deram bom saque e quais lutaram duro. Seu capitão, {link:andre-firebeard}Andre Firebeard{/link}, é procurado pelo Porto de Bondebico e por {link:gadgetzan}Geringontzan{/link} juntos. Dizem que o Cartel um dia pagou aos piratas para deixarem seus navios em paz, e que os piratas começaram a aceitar o dinheiro e atacar mesmo assim.]=],
		},
	},
})

Translate("ptBR", "sandfury-trolls", {
	title = "Trolls Sandfury",
	aliases = { "Sandfury", "trolls Sandfury", "a tribo Sandfury" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Sandfury são os trolls do deserto. Sua cidade é {red:zul-farrak}Zul'Farrak{/red}, no noroeste de {link:tanaris}Tanaris{/link}, e seus guerreiros vigiam de postos avançados como o {link:sandsorrow-watch}Posto Silitriste{/link}. São conhecidos pela crueldade e por um misticismo sombrio que ergue seus mortos para servi-los. Adoram Gahz'rilla, uma grande hidra que invocam de um lago sagrado no coração de sua cidade.]=],
		},
		{
			title = "Seus Ofícios",
			text = [=[Os Sandfury fazem um agente de têmpera com o arenito do deserto, apreciado pelos ferreiros que conhecem um bom metal. Escaravelhos fervilham em sua cidade, onde nenhum troll os caça por suas carapaças. Antigas tabuletas do profeta Mosh'aru, levadas para lá há muito tempo, são guardadas por seus sacerdotes.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[Os Sandfury não têm amigos no deserto. Ferreiros e estudiosos goblins pagam pelo que se pode tirar de sua cidade, e bandos de caçadores de tesouros entram atrás de suas riquezas. Nem todos saem.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica destes dias conta há quanto tempo os Sandfury dominam Zul'Farrak, ou que laço mantêm com as outras tribos trolls.]=],
		},
	},
})

Translate("ptBR", "marin-noggenfogger", {
	title = "Marin Noggenfogger",
	subtitle = "Senhor de Geringontzan",
	found = "Geringontzan, no coração da cidade",
	hint = "Procure o goblin que governa Geringontzan.",
	allegiance = "Geringontzan · Cartel Bondebico",
	aliases = { "Noggenfogger" },
	sections = {
		{
			title = "Resumo",
			text = [=[Marin Noggenfogger é o senhor goblin de {link:gadgetzan}Geringontzan{/link}, a cidade que o {link:steamwheedle-cartel}Cartel Bondebico{/link} ergueu no deserto de {link:tanaris}Tanaris{/link}. Assim como o {link:baron-revilgaz}Barão Revilgaz{/link} governa a {link:booty-bay}Angra do Butim{/link} e {link:gazlowe}Gazlowe{/link} zela por {link:ratchet}Vila Catraca{/link}, Noggenfogger comanda a cidade do Cartel no deserto. É inquieto, sedento e está sempre à caça da próxima grande ideia. Até seus amigos o chamam de excêntrico.]=],
		},
		{
			title = "Importância",
			text = [=[{link:gadgetzan}Geringontzan{/link} fica sobre a única água segura por muitas léguas, e seu senhor governa no cruzamento de todas as estradas do sul. Sob Noggenfogger, a cidade permaneceu terreno neutro. {link:alliance}Aliança{/link} e {link:horde}Horda{/link} descansam igualmente atrás de suas muralhas, e os brutamontes da cidade mantêm a paz. Seu nome também é conhecido muito além do deserto pelo elixir que o leva, com o qual ele pretende fazer fortuna.]=],
		},
		{
			title = "Feitos",
			text = [=[• Governa {link:gadgetzan}Geringontzan{/link} para o {link:steamwheedle-cartel}Cartel Bondebico{/link}.
• Ouviu falar de estranhas criaturas do deserto que armazenam água em suas glândulas, e decidiu preparar uma bebida com elas.
• Com a ajuda de sua amiga {link:sprinkle}Sprinkle{/link}, criou o Elixir de Noggenfogger.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica conta como Noggenfogger chegou a governar {link:gadgetzan}Geringontzan{/link}, ou quem a governava antes dele.]=],
		},
	},
	chapters = {
		{
			title = "O Goblin Sedento",
			hint = [=[Leve ao sedento senhor de Geringontzan o que o jardim de cactos esconde.]=],
			text = [=[A sede de Noggenfogger era tão grande que ele ficou desesperado. Tinha ouvido falar dos coletores de orvalho do {link:thistleshrub-valley}Vale Moitagulhas{/link}, e raciocinou que a água em suas glândulas talvez finalmente a saciasse. Quando lhe trouxeram uma glândula cheia, bebeu-a de uma vez. O gosto era terrível. Quase desistiu, até decidir que uma bebida tão ruim devia ao menos ter algum efeito.]=],
		},
		{
			title = "O Elixir",
			hint = "Ajude o goblin a aperfeiçoar sua bebida.",
			text = [=[{link:sprinkle}Sprinkle{/link}, a cozinheira de {link:gadgetzan}Geringontzan{/link}, conhecia um segredo: um cogumelo violeta que cresce sob a água de um pequeno lago nas {link:the-hinterlands}Terras Agrestes{/link}. Moído até virar pó e misturado ao orvalho, tornava a mistura não apenas bebível, mas maravilhosa. Noggenfogger declarou que ganharia milhões com ela. Quando ouviu que devia um favor a Sprinkle, chamou-a de grande brincalhona.]=],
		},
	},
	mentions = {
		{ text = "De Bom Gosto" },
		{ text = "O Ingrediente Secreto de {link:sprinkle}Sprinkle{/link}" },
		{ text = "Entrega para Marin" },
	},
	bonds = {
		{ id = "sprinkle", name = "Sprinkle", note = "sua amiga e cozinheira" },
		{ id = "chief-engineer-bilgewhizzle", name = "Engenheiro-chefe Bilgewhizzle", note = "cuida da água da cidade" },
		{ id = "baron-revilgaz", name = "Barão Revilgaz", note = "governa a Angra do Butim para o mesmo Cartel" },
		{ id = "gazlowe", name = "Gazlowe", note = "governa Vila Catraca para o mesmo Cartel" },
	},
})

Translate("ptBR", "yeh-kinya", {
	title = "Yeh'kinya",
	subtitle = "Estudioso das Profecias Trolls",
	found = "Porto de Bondebico",
	hint = [=[Procure o troll que estuda antigas profecias entre os caixotes do Porto de Bondebico.]=],
	allegiance = "Desconhecida",
	sections = {
		{
			title = "Resumo",
			text = [=[Yeh'kinya é um troll que vive entre os goblins do {link:steamwheedle-port}Porto de Bondebico{/link}. Conhece as antigas lendas de seu povo melhor que a maioria, sobretudo a lenda de {link:hakkar}Hakkar{/link}, o Esfolador de Almas, o deus morto do sangue. Ele diz que não acredita nas histórias sobre o retorno de Hakkar. Acredita, sim, que a essência do deus guarda grande poder, e decidiu reuni-la.]=],
		},
		{
			title = "Importância",
			text = [=[Yeh'kinya foi quem pôs em movimento o Ovo de {link:hakkar}Hakkar{/link}. Pelos espíritos de feras, pelas tabuletas de um profeta morto e por um ovo escondido numa cidade troll, ele descobriu como a essência do Esfolador de Almas poderia ser capturada e contida. Fala em mantê-la longe dos que abusariam dela. Nem todos acreditam nele.]=],
		},
		{
			title = "Feitos",
			text = [=[• Buscou os espíritos dos guinchadores do vale de {link:feralas}Feralas{/link}, que ele chama de primos de um deus antigo.
• Reuniu as duas primeiras tabuletas do profeta Mosh'aru de {red:zul-farrak}Zul'Farrak{/red} e as fundiu.
• Mandou buscar um ovo ancestral em {link:jintha-alor}Jintha'Alor{/link}, uma relíquia dos impérios trolls.
• Enviou o ovo ao {link:temple-of-atal-hakkar}Templo de Atal'Hakkar{/link}, onde a essência do deus foi capturada.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica conta de que tribo Yeh'kinya vem, ou por que vive entre goblins.]=],
		},
	},
	chapters = {
		{
			title = "Espíritos dos Guinchadores",
			hint = [=[Leve ao troll do Porto de Bondebico os espíritos dos guinchadores de Feralas.]=],
			text = [=[Yeh'kinya queria os espíritos dos guinchadores do vale, pois afirmava que estavam ligados a um deus ancestral. Quando lhe foram trazidos, contou uma antiga profecia troll: que o deus morto {link:hakkar}Hakkar{/link} um dia voltaria ao mundo. Alguns trolls dizem que isso trará glória. Outros dizem que trará o fim de todas as coisas.]=],
		},
		{
			title = "A Profecia de Mosh'aru",
			hint = "Leve ao troll as tabuletas do profeta de Zul'Farrak.",
			text = [=[A profecia de Mosh'aru foi escrita em duas tabuletas e levada a Zul'Farrak. Uma estava com o troll morto Theka, o Mártir, a outra com a hidromante Velratha, junto ao lago sagrado. Yeh'kinya fundiu as tabuletas e leu seu segredo: um ovo ancestral poderia conter a essência de {link:hakkar}Hakkar{/link}.]=],
		},
		{
			title = "O Ovo de Hakkar",
			hint = "Leve o ovo ao templo afogado e traga-o de volta cheio.",
			text = [=[O ovo foi encontrado em {link:jintha-alor}Jintha'Alor{/link} e levado ao Santuário do Deus Caído. O avatar de {link:hakkar}Hakkar{/link} surgiu e caiu, e sua essência foi selada no ovo. Quando o ovo voltou a {link:tanaris}Tanaris{/link}, pulsava de vida. Yeh'kinya pareceu abalado, e jurou mantê-lo a salvo de mãos malignas.]=],
		},
		{
			title = "As Tabuletas Perdidas",
			hint = "Ouça o que o anão do Porto de Bondebico descobriu.",
			text = [=[Um garimpeiro {link:dwarves}anão{/link}, que fica a poucos passos de Yeh'kinya, também estudou a profecia. Ele diz que há seis tabuletas de Mosh'aru, não duas, e que o troll não contou toda a verdade.]=],
		},
	},
	mentions = {
		{ text = "O Ovo Ancestral" },
	},
	bonds = {
		{ id = "hakkar", name = "Hakkar", note = "o deus cuja essência ele reúne" },
		{ id = "avatar-of-hakkar", name = "Avatar de Hakkar", note = "cuja essência enche seu ovo" },
		{ id = "prospector-ironboot", name = "Garimpeiro Ironboot", note = "duvida de sua palavra" },
	},
})

Translate("ptBR", "senior-surveyor-fizzledowser", {
	title = "Agrimensor Sênior Fizzledowser",
	subtitle = "Cia. de Águas de Geringontzan",
	found = "Geringontzan, no lado oeste da cidade",
	hint = "Procure o goblin que vasculha o deserto atrás de água nova.",
	allegiance = "Companhia de Águas de Geringontzan · Geringontzan",
	aliases = { "Fizzledowser" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Agrimensor Sênior Fizzledowser lidera a busca por água no deserto para {link:gadgetzan-water-company}a Companhia de Águas{/link} de {link:gadgetzan}Geringontzan{/link}. Com {link:wastewander-nomads}os nômades{/link} dominando os poços, ele envia agrimensores juniores para a areia com aparelhos de radiestesia para encontrar poças e fontes livres. O que encontraram foi uma ameaça muito maior que qualquer nômade.]=],
		},
		{
			title = "Importância",
			text = [=[Fizzledowser é o goblin que primeiro deu o alarme sobre os insetos de {link:tanaris}Tanaris{/link}. De início, descartou os relatos de estranhas criaturas-inseto sugando água como mais um truque dos nômades. Então seus agrimensores começaram a morrer. Seus relatórios, e os do {link:alchemist-pestlezugg}Alquimista Pestlezugg{/link}, levaram o nome dos {link:qiraji}silitídeos{/link} de {link:gadgetzan}Geringontzan{/link} a {link:orgrimmar}Orgrimmar{/link} e a {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Enviou um agrimensor para testar a poça perto do {link:sandsorrow-watch}Posto Silitriste{/link}, onde veio o primeiro ataque dos insetos.
• Mandou recolher partes dos insetos do {link:the-noxious-lair}Covil Nóxio{/link} para estudo.
• Perdeu seu principal assistente, o Agrimensor Júnior Scrimshank, na {link:the-gaping-chasm}Fenda Hazzali{/link}.
• Concordou em compartilhar livremente o relatório sobre os insetos, contra todos os hábitos de seu ofício.]=],
		},
	},
	chapters = {
		{
			title = "O Levantamento da Água",
			hint = [=[Colha amostra da poça perto da torre de vigia troll para a Companhia de Águas.]=],
			text = [=[O agrimensor que foi à poça do {link:sandsorrow-watch}Posto Silitriste{/link} foi emboscado por uma criatura saída da areia. Fizzledowser admitiu que tinha ouvido falar dessas criaturas. Não tinha acreditado. Agora acreditava, e temia o que isso significava para a companhia.]=],
		},
		{
			title = "A Redenção de Scrimshank",
			hint = [=[Descubra o que foi feito do agrimensor perdido na Fenda Hazzali.]=],
			text = [=[Scrimshank tinha entrado na {link:the-gaping-chasm}Fenda Hazzali{/link}, e seu último relatório falava de mais insetos ali. Só seu equipamento de agrimensura voltou. Fizzledowser pôs pessoalmente em ordem os pertences do jovem goblin. Os registros que Scrimshank deixou sugeriam que os insetos poderiam estar sob o controle de algum terceiro poder.]=],
		},
		{
			title = "A Ascensão dos Silitídeos",
			hint = [=[Leve o relatório sobre os insetos aos estudiosos das grandes cidades.]=],
			text = [=[{link:alchemist-pestlezugg}Pestlezugg{/link} pediu que todos que soubessem ler vissem o relatório. Fizzledowser, que costumava vender conhecimento por boa moeda, fez cópias e as enviou aos estudiosos que conhecia nas capitais. Deles veio o nome do inimigo.]=],
		},
	},
	mentions = {
		{ text = "Investigação do {link:the-noxious-lair}Covil Nóxio{/link}" },
		{ text = "Análise de Partes de Insetos" },
	},
	bonds = {
		{ id = "alchemist-pestlezugg", name = "Alquimista Pestlezugg", note = "estuda os insetos com ele" },
		{ id = "chief-engineer-bilgewhizzle", name = "Engenheiro-chefe Bilgewhizzle", note = "colega de posto na Companhia de Águas" },
	},
})

Translate("ptBR", "chief-engineer-bilgewhizzle", {
	title = "Engenheiro-chefe Bilgewhizzle",
	subtitle = "Cia. de Águas de Geringontzan",
	found = "Geringontzan, sob a torre d'água",
