			text = [=[Mais Justiça contra os {link:wastewander-nomads}Wastewander{/link}]=],
		},
		{
			text = [=[PROCURADO: {link:caliph-scorpidsting}Califa Scorpidsting{/link}]=],
		},
		{ text = "Varinha Adivinhomática" },
	},
})

Translate("ptBR", "alchemist-pestlezugg", {
	title = "Alquimista Pestlezugg",
	subtitle = "Suprimentos de Alquimia",
	found = "Geringontzan",
