	allegiance = "Geringontzan",
	sections = {
		{
			title = "Resumo",
			text = [=[Sprinkle é uma cozinheira de {link:gadgetzan}Geringontzan{/link} e amiga de {link:marin-noggenfogger}Marin Noggenfogger{/link}. Quando criança, sobreviveu à comida da irmã descobrindo um ingrediente secreto: o Violet Tragan, um cogumelo que só cresce sob a água de um lago nas {link:the-hinterlands}Terras Agrestes{/link}. Foi seu pó violeta que transformou o orvalho repugnante de Noggenfogger no elixir que leva o nome dele. Ele lhe deve um favor. Não parece se lembrar disso.]=],
