	allegiance = "Geringontzan",
	sections = {
		{
			title = "Resumo",
			text = [=[Shreev cuida do Gizmorium de {link:gadgetzan}Geringontzan{/link}. Fabrica explosivos, e entre seus clientes estão os corredores goblins da {link:the-shimmering-flats}Chapada Cintilante{/link}. {link:razzeric}Razzeric{/link} encomendou-lhe um propulsor de seafório. Shreev já o havia feito mais potente do que seria seguro, e instalou nele uma trava de segurança. Razzeric o devolveu. Shreev tirou a trava, e advertiu que um só erro deixaria o corredor como uma mancha queimada na pista.]=],
