	allegiance = "Geringontzan",
	sections = {
		{
			title = "Resumo",
			text = [=[Andi Lynn vigia, de {link:gadgetzan}Geringontzan{/link}, os ogros do deserto do sul. Um grande bando de ogros nômades Dunamalho chegou a {link:tanaris}Tanaris{/link} e construiu um complexo no sul, e bandos menores se espalharam pelas antigas ruínas trolls. Ela acredita que o complexo precisa ser destruído antes que os ogros reúnam suas forças, e que a morte de seu líder, {link:gor-marok-the-ravager}Gor'marok, o Devastador{/link}, seria o começo de seu fim.]=],
		},
	},
