		},
	},
	bonds = {
		{ id = "gor-marok-the-ravager", name = "Gor'marok, o Devastador", note = "o ogro que ela quer morto" },
	},
})

Translate("ptBR", "marvon-rivetseeker", {
	title = "Marvon Rivetseeker",
	found = "O Pilar Partido, no meio do deserto",
	hint = [=[Procure o estudioso goblin que acampa entre as ruínas trolls do deserto.]=],
	allegiance = "Vila Catraca",
	aliases = { "Marvon" },
	sections = {
		{
			title = "Resumo",
			text = [=[Marvon Rivetseeker é um goblin de {link:ratchet}Vila Catraca{/link}, um cientista e, segundo ele mesmo, um caçador de tesouros de coração. Estudou muitos lugares antigos do mundo e agora acampa no deserto para estudar suas ruínas trolls. Coleciona os ornamentos de Gahz'ridian, uma pedra que os trolls entalhavam na forma de seu deus-hidra, e construiu um elmo que os encontra. Certa vez entrou no {link:temple-of-atal-hakkar}Templo Submerso{/link} e escapou por pouco. De seu círculo de estátuas de serpentes, lembra-se apenas de fragmentos.]=],
		},
	},
	chapters = {
		{
			title = "O Círculo de Pedra",
			hint = "Ajude o estudioso goblin a se lembrar do Templo Submerso.",
			text = [=[Marvon havia encontrado uma pedra redonda marcada com o mesmo sinal de serpente que vira no templo, e a enviara para sua oficina em {link:ratchet}Vila Catraca{/link}. Quando ela lhe foi trazida, sua memória voltou: seis sacadas, seis estátuas de serpentes e, abaixo, um altar de {link:hakkar}Hakkar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Gahz'ridian" },
		{ text = "O {link:temple-of-atal-hakkar}Templo Submerso{/link}" },
		{ text = "Rumo às {link:blackfathom-deeps}Profundezas{/link}" },
		{ text = "O Segredo do Círculo" },
	},
})

Translate("ptBR", "stoley", {
	title = "Stoley",
	found = "Porto de Bondebico, atrás do balcão",
	hint = "Procure o taberneiro do Porto de Bondebico.",
	allegiance = "Porto de Bondebico",
	sections = {
