			title = "Resumo",
			text = [=[Stoley cuida do bar do {link:steamwheedle-port}Porto de Bondebico{/link}. Certa vez apostou com seu velho amigo {link:sea-wolf-mackinley}"Lobo do Mar" MacKinley{/link}, da {link:booty-bay}Angra do Butim{/link}, que o rum de {link:kalimdor}Kalimdor{/link} era mais forte que qualquer coisa da Angra do Butim, e prometeu dobrar sua dívida se MacKinley discordasse. Então o pirata Capitão Cuergo roubou seu último carregamento e o escondeu na {link:lost-rigger-cove}Enseada do Armador Perdido{/link}. Quando uma garrafa finalmente chegou à Angra do Butim, MacKinley achou o rum terrível, e deu a aposta por perdida.]=],
		},
	},
	mentions = {
		{ text = "A Dívida de Stoley" },
		{ text = "O Carregamento de Stoley" },
		{ text = "Entregue a {link:sea-wolf-mackinley}MacKinley{/link}" },
	},
	bonds = {
		{ id = "sea-wolf-mackinley", name = "\"Lobo do Mar\" MacKinley", note = "seu velho amigo e rival em apostas" },
	},
})

