Translate("ptBR", "prospector-ironboot", {
	title = "Garimpeiro Ironboot",
	found = "Porto de Bondebico",
	hint = [=[Procure o garimpeiro anão do Porto de Bondebico que estuda velhas tabuletas.]=],
	allegiance = "Desconhecida",
	aliases = { "Ironboot" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Garimpeiro Ironboot é um {link:dwarves}anão{/link} que se instalou no {link:steamwheedle-port}Porto de Bondebico{/link}, a poucos passos do troll {link:yeh-kinya}Yeh'kinya{/link}. Há muito tempo estuda a profecia de Mosh'aru, e descobriu que ela foi escrita em seis tabuletas, não em duas. As tabuletas que Yeh'kinya reuniu falavam de conter a essência de {link:hakkar}Hakkar{/link}. Ironboot teme que as outras guardem segredos mais sombrios, e acredita que o troll não disse a verdade.]=],
		},
	},
	chapters = {
		{
			title = "As Tabuletas Perdidas de Mosh'aru",
			hint = "Encontre as tabuletas das quais o troll nunca falou.",
			text = [=[A terceira e a quarta tabuletas estavam com os trolls Mossflayer das {link:eastern-plaguelands}Terras Pestilentas Orientais{/link}. A quinta e a sexta estavam com os trolls Smolderthorn no {link:blackrock-mountain}Pico da Rocha Negra{/link}. Ironboot leu todas. O que descobriu, disse ele, significava que seria preciso um herói.]=],
		},
	},
	mentions = {
		{ text = "As Tabuletas Finais" },
	},
	bonds = {
		{ id = "yeh-kinya", name = "Yeh'kinya", note = "de cuja palavra ele duvida" },
	},
})

Translate("ptBR", "nixx-sprocketspring", {
